#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NSKU 5

/* price table – values taken from the original binary */
static const long price[NSKU] = {10L, 20L, 30L, 40L, 50L};
/* stock table – starts at zero */
static long stock[NSKU] = {0};

int main(int argc, char **argv)
{
    long revenue = 0;
    int arg = 1;                     /* first user argument (argv[0] is the program name) */

    while (arg + 2 < argc) {         /* need three arguments for each operation */
        const char *op = argv[arg];
        long sku   = strtol(argv[arg + 1], NULL, 10);
        long qty   = strtol(argv[arg + 2], NULL, 10);
        arg += 3;

        /* ----- operation validation ----- */
        if (strlen(op) != 1) {
            puts("INVALID_OP");
            continue;
        }
        if (op[0] != 'S' && op[0] != 'R') {
            puts("INVALID_OP");
            continue;
        }

        /* ----- SKU validation ----- */
        if (sku < 0 || sku >= NSKU) {
            puts("INVALID_SKU");
            continue;
        }

        if (op[0] == 'R') {                     /* ----- RESTOCK ----- */
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        } else {                                 /* ----- SELL ----- */
            if (qty < 0 || stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] -= qty;
            revenue += price[sku] * qty;
            printf("SELL sku=%ld qty=%ld revenue+=%ld\n",
                   sku, qty, price[sku] * qty);
        }
    }

    /* ----- final report ----- */
    printf("FINAL stock=");
    for (int i = 0; i < NSKU; ++i) {
        printf("%ld", stock[i]);
        if (i != NSKU - 1)
            putchar(',');
    }
    printf("\n revenue=%ld\n", revenue);
    return 0;
}
